package com.orderflow.notification.security;import com.orderflow.platform.error.ErrorCode;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.http.HttpStatus;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.web.access.AccessDeniedHandler;import org.springframework.stereotype.Component;@Component public class RestAccessDeniedHandler implements AccessDeniedHandler{private final ApiSecurityErrorWriter w;public RestAccessDeniedHandler(ApiSecurityErrorWriter w){this.w=w;}public void handle(HttpServletRequest q,HttpServletResponse p,AccessDeniedException e)throws IOException{w.write(q,p,HttpStatus.FORBIDDEN,ErrorCode.INSUFFICIENT_PERMISSIONS,"You do not have permission to perform this action.");}}
